const ICONS={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',tasks:'M8 5h13 M8 12h13 M8 19h13 M3 5h.01 M3 12h.01 M3 19h.01',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',settings:'M9 3h6l1 4 4 1v8l-4 1-1 4H9l-1-4-4-1V8l4-1z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',plus:'M12 5v14 M5 12h14',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',calendar:'M8 2v4 M16 2v4 M3 9h18 M4 4h16a1 1 0 0 1 1 1v15a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1',check:'M5 12l4 4L19 6',arrow:'M5 12h14 M14 7l5 5-5 5',close:'M6 6l12 12 M6 18L18 6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',shield:'M12 3l9 4v6c0 5-9 9-9 9s-9-4-9-9V7z M8 12l3 3 5-6',trend:'M3 17l6-6 4 4 8-10 M15 5h6v6',edit:'M16 3l5 5-12 12-6 1 1-6z M14 5l5 5',logout:'M9 3H4v18h5 M9 12h12 M17 8l4 4-4 4',refresh:'M20 7a9 9 0 1 0 1 8 M20 2v5h-5',chat:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4',alert:'M12 3L2 21h20z M12 9v5 M12 17h.01',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-3 3 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l3-3'};
const ic=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[n]||ICONS.tasks}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses={todo:'မစတင်ရသေး',doing:'လုပ်နေဆဲ',review:'စစ်ဆေးရန်',done:'ပြီးစီး',blocked:'အခက်အခဲရှိ'};
const priorities={low:'နိမ့်',normal:'ပုံမှန်',high:'အရေးကြီး',urgent:'အရေးပေါ်'};
const roles={ceo:'CEO',admin:'Admin',employee:'ဝန်ထမ်း'};
const pages={dashboard:'ခြုံငုံသုံးသပ်ချက်',tasks:'အလုပ်တာဝန်များ',people:'ဝန်ထမ်းများ',notifications:'အသိပေးချက်များ',settings:'ဆက်တင်များ'};
const palette=['#e7eedb','#e6eef5','#f3e7da','#ece6f2','#e1ede7'];
let S={me:null,people:[],tasks:[],comments:[],attachments:[],activity:[],filesReady:false},page='dashboard',filter='all',query='',priorityFilter='all',personFilter='all',demo=false,stale=false,deferredInstall=null,notificationReady=false,refreshing=false,pushState='unknown',noticesLoaded=false,searchTimer=null,peopleView='cards';
try{peopleView=localStorage.getItem('linn-people-view')==='table'?'table':'cards';}catch{}
const isAdmin=()=>['ceo','admin'].includes(S.me?.role);
const canManagePerson=p=>S.me?.role==='ceo'||(S.me?.role==='admin'&&p?.role==='employee');
const person=id=>S.people.find(p=>p.id===id);
const names=ids=>ids.map(id=>person(id)?.name||'ဝန်ထမ်း').join('၊ ');
const initials=name=>{const words=String(name||'L').split(/\s+/);return words[0].slice(0,1).toUpperCase()+(words[1]?.slice(0,1).toUpperCase()||'');};
const avatar=(p,large=false)=>`<span class="avatar${large?' large':''}${p?.hasPhoto?' has-photo':''}" style="background:${palette[Math.max(0,S.people.indexOf(p))%palette.length]}" title="${esc(p?.name)}">${p?.hasPhoto?`<img src="/api/employees/${encodeURIComponent(p.id)}/photo?v=${encodeURIComponent(p.photoUpdatedAt||'1')}" alt="${esc(p.name)}" loading="lazy" decoding="async">`:esc(initials(p?.name))}</span>`;
const group=ids=>`<div class="avatar-group">${ids.slice(0,3).map(id=>avatar(person(id))).join('')}${ids.length>3?`<span class="avatar">+${ids.length-3}</span>`:''}</div>`;
const mmDigits=v=>String(v).replace(/[0-9]/g,n=>'၀၁၂၃၄၅၆၇၈၉'[Number(n)]);
const myDate=(v,options={})=>{const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Rangoon',month:'numeric',day:'numeric',...(options.year?{year:'numeric'}:{}),...(options.weekday?{weekday:'long'}:{}),...(options.hour?{hour:'2-digit',minute:'2-digit',hourCycle:'h23'}:{})}).formatToParts(new Date(v));const get=k=>parts.find(p=>p.type===k)?.value;const months=['ဇန်နဝါရီ','ဖေဖော်ဝါရီ','မတ်','ဧပြီ','မေ','ဇွန်','ဇူလိုင်','ဩဂုတ်','စက်တင်ဘာ','အောက်တိုဘာ','နိုဝင်ဘာ','ဒီဇင်ဘာ'];const weekdays={Monday:'တနင်္လာ',Tuesday:'အင်္ဂါ',Wednesday:'ဗုဒ္ဓဟူး',Thursday:'ကြာသပတေး',Friday:'သောကြာ',Saturday:'စနေ',Sunday:'တနင်္ဂနွေ'};return `${options.weekday?weekdays[get('weekday')]+'နေ့၊ ':''}${mmDigits(get('day'))} ${months[Number(get('month'))-1]}${options.year?' '+mmDigits(get('year')):''}${options.hour?'၊ '+mmDigits(get('hour')+':'+get('minute')):''}`;};
const dateTime=v=>myDate(v,{year:'numeric',hour:'numeric',minute:'2-digit'});
const wall=v=>{const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Rangoon',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(v));const get=t=>p.find(x=>x.type===t).value;return `${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}`;};
const toUTC=v=>new Date(v+'+06:30').toISOString();
const late=t=>t.status!=='done'&&new Date(t.deadline)<new Date();
const soon=t=>t.status!=='done'&&!late(t)&&new Date(t.deadline)-new Date()<86400000;
const progress=t=>`<div class="task-progress"><div class="progress"><span style="width:${t.progress}%"></span></div><span>${t.progress}%</span></div>`;
const badge=(s,map=statuses)=>`<span class="badge ${esc(s)}">${esc(map[s]||s)}</span>`;
const due=t=>`<span class="deadline ${late(t)?'late':soon(t)?'soon':''}">${ic('calendar')}${esc(myDate(t.deadline,{hour:'numeric',minute:'2-digit'}))}</span>`;
const btn=(label,action,icon='plus',kind='primary',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${ic(icon)}${label}</button>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function empty(title,desc,action=''){return `<div class="empty"><div class="empty-icon">${ic('tasks')}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`;}
const previewImageTypes=new Set(['image/jpeg','image/png','image/gif','image/webp','image/avif']);
function attachmentMarkup(a){const size=Math.ceil(a.size/1024)+' KB',url='/api/files/'+encodeURIComponent(a.id);if(!demo&&previewImageTypes.has(a.content_type))return `<article class="photo-attachment"><button type="button" class="photo-thumb" data-action="preview-photo" data-id="${esc(a.id)}" data-name="${esc(a.name)}" aria-label="${esc(a.name)} ပုံကို အပြည့်ကြည့်ရန်"><img src="${url}?preview=1" alt="${esc(a.name)}" loading="lazy"></button><div class="photo-meta"><strong>${esc(a.name)}</strong><small>${size}</small><a class="btn small" href="${url}" download>${ic('download')} ဒေါင်းလုဒ်</a></div></article>`;return demo?`<div class="attachment">${ic('file')} ${esc(a.name)}<small>${size}</small></div>`:`<a class="attachment" href="${url}" download>${ic('file')} ${esc(a.name)}<small>${size} ${ic('download')}</small></a>`;}
function previewPhoto(id,name){let viewer=$('#photo-viewer');if(!viewer){viewer=document.createElement('dialog');viewer.id='photo-viewer';viewer.className='photo-viewer';viewer.addEventListener('close',()=>document.body.classList.remove('photo-open'));document.body.append(viewer);}viewer.innerHTML=`<div class="photo-viewer-bar"><strong>${esc(name)}</strong><button class="icon-btn" data-action="close-photo" aria-label="ပုံပိတ်ရန်">${ic('close')}</button></div><img src="/api/files/${encodeURIComponent(id)}?preview=1" alt="${esc(name)}"><a class="btn" href="/api/files/${encodeURIComponent(id)}" download>${ic('download')} မူရင်းဖိုင် ဒေါင်းလုဒ်</a>`;if(!viewer.open)viewer.showModal();viewer.classList.add('open');document.body.classList.add('photo-open');viewer.querySelector('button').focus();}
function closePhoto(){const viewer=$('#photo-viewer');if(viewer?.open)viewer.close();viewer?.classList.remove('open');document.body.classList.remove('photo-open');}
async function request(path,method='GET',data){
 if(demo)return demoRequest(path,method,data);
 if(!navigator.onLine&&method!=='GET')throw Error('အင်တာနက်မရှိပါ။ ချိတ်ဆက်ပြီးမှ ပြန်သိမ်းပါ');
 const headers={'X-Linn-Client':'1'};let body;
 if(data instanceof FormData)body=data;else if(data!==undefined){headers['Content-Type']='application/json';body=JSON.stringify(data);}
 const r=await fetch(path,{method,headers,body,credentials:'same-origin',cache:'no-store'});let result;try{result=await r.json();}catch{throw Error('အကောင့် သို့မဟုတ် ချိတ်ဆက်မှုကို စစ်ပါ');}
 if(!r.ok){if(result.code==='PASSWORD_CHANGE_REQUIRED')requiredPasswordScreen(result.me);if(r.status===401&&!path.startsWith('/api/auth/')){lockSession();result.error='အကောင့်ဝင်ချိန် ကုန်ဆုံးသွားသည်။ Email/password ဖြင့် ပြန်ဝင်ပါ';}throw Error(result.error||'လုပ်ဆောင်မှု မအောင်မြင်ပါ');}if(path==='/api/auth/change-password')restoredPushFor=null;return result;
}
function navMarkup(mobile=false){const items=[['dashboard','grid'],['tasks','tasks'],...(isAdmin()?[['people','people']]:[]),...(mobile?[]:[['notifications','bell']]),['settings','settings']];return items.map(([p,i])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${ic(i)}<span>${pages[p]}</span>${!mobile&&p==='tasks'?`<span class="nav-count">${S.tasks.filter(t=>t.status!=='done').length}</span>`:''}</button>`).join('');}
const brand=()=>`<div class="brand"><img class="brand-logo" src="/logo.png" width="1200" height="648" alt="Linn IT Solutions" decoding="async"></div>`;
function goPage(next){if(page===next)return;const update=()=>{page=next;if(page==='tasks')filter='all';render();window.scrollTo({top:0,behavior:'auto'});};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.startViewTransition(update);else update();}
function render(){
 if(!S.me)return;
 app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="workspace-label uppercase">Workspace</div><nav class="nav" aria-label="ပင်မမီနူး">${navMarkup()}</nav><div class="sidebar-foot"><div class="support-card">${ic('download')}<h3>ဖုန်းမှာ ထည့်သုံးပါ</h3><p>အလုပ်တာဝန်များကို အချိန်မရွေး လွယ်လွယ်ကူကူ ကြည့်နိုင်သည်။</p>${btn('App ထည့်သွင်းရန်','install','arrow','')}</div><div class="user">${avatar(S.me)}<div><strong>${esc(S.me.name)}</strong><small>${roles[S.me.role]} · Linn IT</small></div></div></div></aside><main class="main"><header class="topbar"><div class="mobile-brand">${brand()}</div><div class="breadcrumb"><span>Linn IT Solutions</span>${ic('arrow')}<strong>${pages[page]}</strong></div><div class="top-actions"><span class="live-pill"><i class="dot ${stale||!navigator.onLine?'off':''}"></i>${demo?'စမ်းသပ်မုဒ်':stale||!navigator.onLine?'ချိတ်ဆက်မှုစစ်ပါ':'ချိတ်ဆက်ထားသည်'}</span><button class="icon-btn ${notifications().some(n=>!n.read)?'badged':''}" data-page="notifications" aria-label="အသိပေးချက်များ">${ic('bell')}</button>${avatar(S.me)}</div></header><div class="content">${demo?`<div class="demo-banner"><span>စမ်းသပ်မုဒ် · နမူနာဒေတာသာ ဖြစ်သည်။ အမှန်တကယ် ဝန်ထမ်းဒေတာ မထည့်ပါနှင့်။</span><select id="demo-role" aria-label="စမ်းသပ်မည့် အကောင့်">${S.people.filter(p=>p.active).map(p=>`<option value="${p.id}" ${p.id===S.me.id?'selected':''}>${esc(p.name)} · ${roles[p.role]}</option>`).join('')}</select><button class="btn small" data-action="exit-demo">ထွက်ရန်</button></div>`:''}${stale||!navigator.onLine?'<div class="offline-banner">အင်တာနက်ချိတ်ဆက်မှု မရပါ။ ပြထားသောဒေတာသည် နောက်ဆုံးရယူထားသောဒေတာ ဖြစ်သည်။ သိမ်းရန် အင်တာနက်လိုအပ်သည်။</div>':''}${({dashboard:dashboard,tasks:taskPage,people:peoplePage,notifications:notificationPage,settings:settingsPage}[page]||dashboard)()}</div></main><nav class="bottom-nav" aria-label="ဖုန်းမီနူး">${navMarkup(true)}</nav></div>`;
}
function pageTitle(title,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">${esc(myDate(new Date(),{weekday:'long',year:'numeric'}))} · မြန်မာစံတော်ချိန်</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function taskRow(t){return `<div class="task-row" role="button" tabindex="0" data-task="${t.id}" aria-label="${esc(t.title)}"><div class="task-check ${t.status==='done'?'done':''}">${t.status==='done'?ic('check'):''}</div><div class="task-body"><h3>${esc(t.title)}</h3><div class="task-meta">${badge(t.priority,priorities)}${due(t)}<span class="collab-text">${ic('people')} ${t.assignees.length+t.collaborators.length} ဦး</span></div></div><div class="task-side">${badge(t.status)}${progress(t)}</div></div>`;}
function dashboard(){
 const all=S.tasks.length,done=S.tasks.filter(t=>t.status==='done').length,doing=S.tasks.filter(t=>t.status==='doing').length,over=S.tasks.filter(late).length,pct=all?Math.round(done/all*100):0;
 const todayTasks=S.tasks.filter(t=>t.status!=='done').sort((a,b)=>new Date(a.deadline)-new Date(b.deadline));
 const list=(filter==='all'?S.tasks:filter==='overdue'?S.tasks.filter(late):S.tasks.filter(t=>t.status===filter)).slice(0,6);
 const activePeople=S.people.filter(p=>p.active).map(p=>({...p,count:S.tasks.filter(t=>t.status!=='done'&&(t.assignees.includes(p.id)||t.collaborators.includes(p.id))).length})).sort((a,b)=>b.count-a.count).slice(0,4);
 return `${pageTitle(isAdmin()?'အဖွဲ့ရဲ့ အလုပ်အခြေအနေ':'ကျွန်ုပ်၏ အလုပ်အခြေအနေ',isAdmin()?'တာဝန်ပေးထားသော အလုပ်များကို တစ်နေရာတည်းမှာ စီမံပါ။':'မိမိတာဝန်များနှင့် ပူးပေါင်းဆောင်ရွက်ရမည့် အလုပ်များ။',isAdmin()?btn('အလုပ်အသစ်','new-task'):btn('ပြန်တင်ရန်','refresh','refresh',''))}<div class="stats">${[['အလုပ်တာဝန် စုစုပေါင်း',all,'tasks','','တာဝန်ယူ / ပူးပေါင်း လုပ်ငန်းများ'],['လုပ်ဆောင်နေဆဲ',doing,'clock','orange','လက်ရှိ အကောင်အထည်ဖော်နေသည်'],['ပြီးစီးသော အလုပ်များ',done,'check','blue',`${pct}% ပြီးစီးမှုနှုန်း`],['သတ်မှတ်ချိန် ကျော်နေ',over,'alert','red','နောက်ကျနေသော အလုပ်များကို စစ်ပါ']].map(([label,n,icon,c,foot])=>`<div class="stat ${c}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${ic(icon)}</span></div><div class="stat-num">${n.toString().padStart(2,'0')}</div><div class="stat-foot">${ic(c==='red'?'clock':'trend')}${foot}</div></div>`).join('')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>အလုပ်တာဝန်များ</h2><small>နောက်ဆုံး ပြောင်းလဲထားသော အလုပ်များ</small></div><button class="text-btn" data-page="tasks">အားလုံးကြည့်မည် ${ic('arrow')}</button></div><div class="tabs">${[['all','အားလုံး'],['doing','လုပ်နေဆဲ'],['review','စစ်ဆေးရန်'],['overdue','နောက်ကျနေ']].map(([id,l])=>`<button class="tab ${filter===id?'active':''}" data-filter="${id}">${l}</button>`).join('')}</div>${list.length?list.map(taskRow).join(''):empty('အလုပ်တာဝန် မရှိသေးပါ','အလုပ်အသစ်ဖန်တီးပြီး တာဝန်ယူမည့်သူနဲ့ ပူးပေါင်းလုပ်သူများကို ရွေးပါ။',isAdmin()?btn('အလုပ်ဖန်တီးရန်','new-task'):'')}</section><div class="section-row"><h2>အဖွဲ့၏ တိုးတက်မှု</h2><span class="muted" style="font-size:10px">အလုပ် ${all} ခုမှ</span></div><section class="panel"><div class="panel-body"><div class="donut" style="--value:${pct}%"><span>${pct}%</span></div><div class="legend"><span><i></i>ပြီးစီး ${done}</span><span><i class="grey"></i>ကျန်ရှိ ${all-done}</span></div></div></section></div><div class="stack"><section class="focus-panel"><div class="uppercase">Better together</div><h2>ရည်မှန်းချက်တူ၊ အောင်မြင်မှုတူ</h2><p>တာဝန်များကို ရှင်းရှင်းလင်းလင်း ခွဲဝေပြီး အဖွဲ့တစ်ခုလုံး၏ တိုးတက်မှုကို မြင်တွေ့ပါ။</p><div class="focus-bottom"><span class="focus-percent">${pct}%</span><small>အလုပ်ပြီးစီးမှုနှုန်း<br>${done} / ${all} အလုပ်များ</small>${ic('trend')}</div><div class="progress"><span style="width:${pct}%"></span></div></section><section class="panel"><div class="panel-head"><h2>မကြာမီ ပြီးစီးရမည့်အလုပ်</h2>${ic('calendar')}</div><div class="panel-body">${todayTasks.length?todayTasks.slice(0,3).map(t=>`<div class="due-item" role="button" tabindex="0" data-task="${t.id}"><div class="date-block"><b>${new Intl.DateTimeFormat('en',{day:'2-digit',timeZone:'Asia/Rangoon'}).format(new Date(t.deadline))}</b><small>${new Intl.DateTimeFormat('en',{month:'short',timeZone:'Asia/Rangoon'}).format(new Date(t.deadline)).toUpperCase()}</small></div><div><h3>${esc(t.title)}</h3><p>${esc(names(t.assignees))}</p><span class="deadline ${late(t)?'late':''}" style="font-size:9px">${late(t)?'သတ်မှတ်ချိန်ကျော်နေသည်':esc(myDate(t.deadline,{hour:'numeric',minute:'2-digit'}))}</span></div></div>`).join(''):'<p class="muted" style="font-size:11px">လက်ရှိ ပြီးစီးရန် အလုပ်မရှိပါ။</p>'}</div></section><section class="panel"><div class="panel-head"><h2>${isAdmin()?'ဝန်ထမ်း အလုပ်ခွဲဝေမှု':'ပူးပေါင်းဆောင်ရွက်သူများ'}</h2>${ic('people')}</div><div class="panel-body">${activePeople.map(p=>`<div class="workload-row">${avatar(person(p.id))}<div class="workload-info"><strong>${esc(p.name)}</strong><div class="progress"><span style="width:${Math.min(100,p.count/Math.max(1,...activePeople.map(x=>x.count))*100)}%"></span></div></div><small>${p.count} ခု</small></div>`).join('')}</div></section></div></div>`;
}
function taskPage(){
 let tasks=S.tasks.filter(t=>(filter==='all'||(filter==='overdue'?late(t):t.status===filter))&&(priorityFilter==='all'||t.priority===priorityFilter)&&(personFilter==='all'||[...t.assignees,...t.collaborators].includes(personFilter))&&(!query||`${t.title} ${t.details} ${names(t.assignees)} ${names(t.collaborators)}`.toLowerCase().includes(query.toLowerCase())));
 return `${pageTitle('အလုပ်တာဝန်များ',`တာဝန်ယူသူ၊ ပူးပေါင်းလုပ်သူနှင့် ပြီးစီးချိန်များကို စီမံပါ။`,isAdmin()?btn('အလုပ်အသစ်','new-task'):'')}<div class="toolbar"><div class="search">${ic('search')}<input type="search" id="task-search" placeholder="အလုပ် သို့မဟုတ် ဝန်ထမ်းအမည် ရှာရန်" aria-label="အလုပ်ရှာရန်" value="${esc(query)}"></div><select id="status-filter" aria-label="အခြေအနေဖြင့် စစ်ထုတ်ရန်"><option value="all">အခြေအနေ အားလုံး</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}<option value="overdue" ${filter==='overdue'?'selected':''}>သတ်မှတ်ချိန်ကျော်</option></select><select id="priority-filter" aria-label="ဦးစားပေးအဆင့်"><option value="all">ဦးစားပေး အားလုံး</option>${Object.entries(priorities).map(([k,v])=>`<option value="${k}" ${priorityFilter===k?'selected':''}>${v}</option>`).join('')}</select><select id="person-filter" aria-label="ဝန်ထမ်းရွေးရန်"><option value="all">ဝန်ထမ်း အားလုံး</option>${S.people.map(p=>`<option value="${p.id}" ${personFilter===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div id="task-results"><div class="section-row"><small class="muted">အလုပ် ${tasks.length} ခု</small>${btn('စာရင်းထုတ်ယူရန်','export-tasks','download','small')}</div>${tasks.length?`<div class="task-grid">${tasks.map(t=>`<article class="task-card" role="button" tabindex="0" data-task="${t.id}"><div class="task-card-top">${badge(t.priority,priorities)}${badge(t.status)}</div><h3>${esc(t.title)}</h3><p>${esc(t.details||'အသေးစိတ်ကို ကြည့်ရန် အလုပ်ကို နှိပ်ပါ။')}</p>${progress(t)}<div class="task-card-bottom">${group([...t.assignees,...t.collaborators])}${due(t)}</div></article>`).join('')}</div>`:`<div class="panel">${empty('အလုပ် မတွေ့ပါ','အလုပ်အသစ် ဖန်တီးပါ သို့မဟုတ် ရှာဖွေရန် စစ်ထုတ်ထားသော အချက်များကို ပြန်ရွေးပါ။',isAdmin()?btn('အလုပ်အသစ်','new-task'):'')}</div>`}</div>`;
}
function peoplePage(){
 if(!isAdmin())return empty('ကြည့်ခွင့်မရှိပါ','Admin သာ ဝန်ထမ်းစာရင်းကို စီမံနိုင်ပါသည်။');
 const rows=S.people.map(p=>({...p,count:S.tasks.filter(t=>t.status!=='done'&&[...t.assignees,...t.collaborators].includes(p.id)).length}));
 const controls=`<div class="people-page-actions"><div class="view-toggle" role="group" aria-label="စာရင်းပုံစံ"><button class="${peopleView==='cards'?'active':''}" data-action="people-view" data-view="cards">${ic('grid')} Card</button><button class="${peopleView==='table'?'active':''}" data-action="people-view" data-view="table">${ic('tasks')} Table</button></div>${btn('ဝန်ထမ်းထည့်ရန်','new-person','plus')}</div>`;
 const cards=`<div class="employees-grid">${rows.map(p=>`<article class="employee-card ${p.active?'':'inactive'}"><div class="employee-card-top">${avatar(p,true)}<div><h3>${esc(p.name)}</h3><p>${esc(p.department||'Linn IT Solutions')}</p></div></div><p class="employee-email">${esc(p.email)}</p>${!demo&&p.active&&p.id!==S.me.id&&(S.me.role==='ceo'||p.role==='employee')?`<button class="btn small" data-action="temporary-person" data-id="${p.id}">${p.linked?'ယာယီ password ပြန်ပေးရန်':'ယာယီ password ပေးရန်'}</button>`:''}<div class="employee-card-bottom"><span>${badge(p.role,roles)} ${p.active?`${p.count} အလုပ်`:'ပိတ်ထားသည်'}</span>${canManagePerson(p)?`<button class="text-btn" data-action="edit-person" data-id="${p.id}">${ic('edit')} ပြင်ရန်</button>`:`<small class="muted">${p.mustChangePassword?'ယာယီ password':p.linked?'Password သတ်မှတ်ပြီး':'Password မသတ်မှတ်ရသေး'}</small>`}</div></article>`).join('')}</div>`;
 const table=`<div class="employee-table-wrap"><table class="employee-table"><thead><tr><th>ဝန်ထမ်း</th><th>Email</th><th>ဌာန / အဖွဲ့</th><th>အဆင့်</th><th>အလုပ်</th><th>အခြေအနေ</th><th><span class="sr-only">လုပ်ဆောင်ချက်</span></th></tr></thead><tbody>${rows.map(p=>`<tr class="${p.active?'':'inactive'}"><td><div class="employee-table-person">${avatar(p)}<strong>${esc(p.name)}</strong></div></td><td>${esc(p.email)}</td><td>${esc(p.department||'Linn IT Solutions')}</td><td>${badge(p.role,roles)}</td><td>${p.count} ခု</td><td>${p.active?'အသုံးပြုနေသည်':'ပိတ်ထားသည်'}</td><td>${canManagePerson(p)?`<button class="btn small" data-action="edit-person" data-id="${p.id}">${ic('edit')} ပြင်ရန်</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;
 return `${pageTitle('ဝန်ထမ်းများ',`လက်ရှိ ဝန်ထမ်း ${S.people.filter(p=>p.active).length} ဦး · တာဝန်နှင့် ခွင့်ပြုချက်များ`,controls)}<div class="note warning">ဝန်ထမ်းအသစ်ကို ယာယီ password ပေးနိုင်သည်။ ပထမဆုံးဝင်ချိန်တွင် မိမိ password အသစ် ပြောင်းရပါမည်။</div>${peopleView==='table'?table:cards}`;
}
const actionLabels={task_created:'အလုပ်အသစ် တာဝန်ပေးထားသည်',task_updated:'အလုပ်အခြေအနေ ပြောင်းထားသည်',comment_added:'မှတ်ချက်အသစ် ရေးထားသည်',attachment_added:'ဖိုင်အသစ် တွဲထားသည်',due:'ပြီးစီးချိန် နီးလာပါပြီ',overdue:'သတ်မှတ်ချိန် ကျော်နေပါပြီ',test:'စမ်းသပ် အသိပေးချက်'};
function notifications(){if(demo)return S.activity.filter(a=>a.employee_id!==S.me?.id).map(a=>({id:a.id,task:a.task_id,title:actionLabels[a.action]||'အပြောင်းအလဲအသစ်',body:S.tasks.find(t=>t.id===a.task_id)?.title||'အဖွဲ့ အပြောင်းအလဲ',date:a.created_at,type:'bell',read:false}));return (S.notices||[]).map(n=>({id:n.id,task:n.task_id,title:actionLabels[n.kind]||'အသိပေးချက်',body:n.body,date:n.created_at,type:['due','overdue'].includes(n.kind)?'alert':'bell',read:!!n.read_at}));}
function pushStatus(){if(demo)return 'နမူနာမုဒ် · ဖုန်းသို့ မပို့ပါ';if(pushState==='enabled')return 'ဤဖုန်းတွင် push notification ဖွင့်ထားသည်';if(pushState==='blocked')return 'ဤဖုန်းတွင် သတိပေးခွင့် ပိတ်ထားသည်';if(pushState==='unsupported')return 'Chrome / Safari မှ app ကို ထည့်သုံးပြီး သတိပေးခွင့် ဖွင့်ပါ';if(pushState==='error')return 'ဖုန်းအသိပေးချက် ချိတ်ဆက်မှု မအောင်မြင်ပါ။ ပြန်ဖွင့်ပါ';return 'ဤဖုန်းတွင် သတိပေးခွင့် ဖွင့်ရန် လိုသည်';}
function notificationPage(){const items=notifications(),unread=items.filter(n=>!n.read).length;return pageTitle('အသိပေးချက်များ','မဖတ်ရသေးသော အသိပေးချက် '+unread+' ခု',btn('သတိပေးခွင့်ဖွင့်ရန်','enable-notifications','bell',''))+'<div class="panel notification-controls"><p>'+esc(pushStatus())+'</p>'+btn('စမ်းပို့ရန်','test-notifications','bell','small')+btn('အားလုံး ဖတ်ပြီး','read-notifications','check','small')+'</div><div class="note">အလုပ်အသစ်၊ ပြောင်းလဲမှု၊ မှတ်ချက်နှင့် ဖိုင်အသစ်များကို ဒီနေရာမှာ ကြည့်နိုင်သည်။ ဖုန်းသတိပေးခွင့် ဖွင့်ထားပါက app ပိတ်ထားချိန်လည်း အလုပ်ပြောင်းလဲမှုများ ပို့ပေးနိုင်သည်။ Deadline ကို server စနစ်က နာရီတိုင်း စစ်ပေးပြီး app ဖွင့်ချိန်တွင်လည်း ချက်ချင်းစစ်ပေးသည်။</div><section class="panel">'+(items.length?items.map(n=>'<div class="notification '+(n.read?'read':'unread')+'"><div class="stat-icon">'+ic(n.type)+'</div><div class="notification-body"><h3>'+esc(n.title)+'</h3><p>'+esc(n.body)+'</p><time>'+esc(dateTime(n.date))+'</time><div class="notification-actions">'+(n.task?btn('အလုပ်ကြည့်ရန်','open-notification','arrow','small','data-id="'+n.id+'" data-task-id="'+n.task+'"'):'')+(!n.read?btn('ဖတ်ပြီး','read-notification','check','small','data-id="'+n.id+'"'):'')+'</div></div></div>').join(''):empty(noticesLoaded?'အသိပေးချက် မရှိသေးပါ':'အသိပေးချက် ရယူမရပါ',noticesLoaded?'သက်ဆိုင်ရာ အလုပ်အသစ်နှင့် ပြောင်းလဲမှုများကို ဤနေရာတွင် ပြမည်။':'အင်တာနက်ကို စစ်ပြီး ပြန်တင်ပါ။',btn('ပြန်တင်ရန်','refresh','refresh','')) )+'</section>';}
function settingsPage(){return `${pageTitle('ဆက်တင်များ','အကောင့်၊ App ထည့်သွင်းခြင်းနှင့် ဒေတာထုတ်ယူခြင်း။')}<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>အကောင့်နှင့် အဖွဲ့</h2>${ic('shield')}</div><div class="panel-body"><div class="user" style="border:0;padding:0 0 16px">${avatar(S.me,true)}<div><strong>${esc(S.me.name)}</strong><small>${esc(S.me.email)} · ${roles[S.me.role]}</small></div></div><div class="settings-row"><div><h3>အမည်နှင့် ဌာန</h3><p>Management အပါအဝင် မိမိအမည်နှင့် ဌာနကို ပြင်နိုင်သည်။</p></div>${btn('ပြင်ရန်','edit-profile','edit','small')}</div><div class="settings-row"><div><h3>လုပ်ငန်းအမည်</h3><p>Linn IT Solutions</p></div>${badge(S.me.role,roles)}</div><div class="settings-row"><div><h3>အချိန်ဇုန်</h3><p>မြန်မာစံတော်ချိန် · UTC +06:30<br>ရက်စွဲနှင့် အချိန်အားလုံးသည် မြန်မာစံတော်ချိန်ဖြစ်သည်။</p></div>${ic('clock')}</div><div class="settings-row"><div><h3>အချက်အလက်သိမ်းဆည်းမှု</h3><p>${demo?'စမ်းသပ်ဒေတာ · ဤ browser တွင်သာ သိမ်းသည်':'Cloud database · အကောင့်ခွင့်ပြုချက်ကို server မှ စစ်ဆေးသည်'}<br>တွဲဖိုင်တစ်ဖိုင် 10 MB အထိ။</p></div>${ic('shield')}</div>${!demo?`<div class="settings-row"><div><h3>Password ပြောင်းရန်</h3><p>ပြောင်းပြီးပါက တခြားဖုန်းများမှ အကောင့်ကို ထွက်ပေးမည်။</p></div>${btn('ပြောင်းရန်','change-password','shield','small')}</div>`:''}<div class="settings-row"><div><h3>အကောင့်မှ ထွက်ရန်</h3><p>မျှဝေသုံးသော ဖုန်းများတွင် အသုံးပြုပြီးပါက ထွက်ပါ။</p></div>${demo?btn('ထွက်ရန်','exit-demo','logout','small'):btn('ထွက်ရန်','logout','logout','small')}</div></div></section><section class="panel"><div class="panel-head"><h2>App နှင့် ဒေတာ</h2>${ic('settings')}</div><div class="panel-body"><div class="settings-row"><div><h3>ဖုန်းမှာ App ထည့်ရန်</h3><p>Android: Chrome → Install app<br>iPhone: Safari → Share → Add to Home Screen</p></div>${btn('ထည့်ရန်','install','download','small')}</div><div class="settings-row"><div><h3>သတိပေးချက်များ</h3><p>${esc(pushStatus())}<br>ဖုန်းသို့ စမ်းပို့ပြီး စစ်ဆေးနိုင်သည်။</p></div>${btn('ခွင့်ဖွင့်ရန်','enable-notifications','bell','small')}</div><div class="settings-row"><div><h3>အလုပ်စာရင်း ထုတ်ယူရန်</h3><p>မိမိကြည့်ခွင့်ရှိသော အလုပ်များကို CSV ဖိုင်ဖြင့် ရယူပါ။</p></div>${btn('ထုတ်ယူရန်','export-tasks','download','small')}</div>${isAdmin()?`<div class="settings-row"><div><h3>အဖွဲ့ဒေတာ အရန်ကူးရန်</h3><p>အလုပ်၊ ဝန်ထမ်း၊ မှတ်ချက်နှင့် ဖိုင်အမည်စာရင်း။ တွဲဖိုင်များကို သီးခြားဒေါင်းလုဒ်လုပ်ပါ။</p></div>${btn('အရန်ကူးရန်','backup','download','small')}</div>`:''}<div class="note">${demo?'စမ်းသပ်မုဒ်တွင် CEO နှင့် ဝန်ထမ်းအကောင့်များ ပြောင်းရွေးပြီး စမ်းကြည့်နိုင်သည်။':'ဝန်ထမ်းများသည် သက်ဆိုင်ရာအလုပ်ကိုသာ ကြည့်ပြီး တိုးတက်မှု၊ အခြေအနေ၊ မှတ်ချက်နှင့် တွဲဖိုင်များ ပြင်နိုင်သည်။ Admin က တာဝန်ပေးပြီး CEO က Admin ခွင့်များ စီမံနိုင်သည်။'}</div>${!demo?btn('နမူနာဖြင့် စမ်းကြည့်ရန်','start-demo','grid','soft'):btn('စမ်းသပ်ဒေတာ ပြန်စရန်','reset-demo','refresh','soft')}</div></section></div>`;}
function showModal(title,subtitle,body,footer=''){modal.innerHTML=`<div class="modal-header"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="icon-btn" data-action="close-modal" aria-label="ပိတ်ရန်">${ic('close')}</button></div><div class="modal-body"><div id="form-error" class="form-error" role="alert"></div>${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
const options=(map,value)=>Object.entries(map).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${v}</option>`).join('');
const peopleInputs=(name,selected)=>`<div class="people-select">${S.people.filter(p=>p.active||selected.includes(p.id)).map(p=>`<label class="person-option"><input type="checkbox" name="${name}" value="${p.id}" ${selected.includes(p.id)?'checked':''}>${esc(p.name)}${!p.active?' (ပိတ်ထား)':''}</label>`).join('')}</div>`;
function taskForm(id){if(!isAdmin())return;const existing=S.tasks.find(t=>t.id===id),t=existing||{title:'',details:'',assignees:[],collaborators:[],start:new Date().toISOString(),deadline:new Date(Date.now()+86400000).toISOString(),status:'todo',priority:'normal',progress:0,reminder:60};showModal(existing?'အလုပ်တာဝန် ပြင်ဆင်ရန်':'အလုပ်တာဝန် အသစ်', 'စတင်ချိန်နှင့် ပြီးစီးချိန်အားလုံးသည် မြန်မာစံတော်ချိန်ဖြစ်သည်။',`<form id="task-form" data-version="${t.version||1}" data-id="${id||''}"><div class="form-grid"><div class="field full"><label for="title">အလုပ်ခေါင်းစဉ် <span class="required">*</span></label><input type="text" id="title" name="title" maxlength="160" required placeholder="ဥပမာ — ရုံး Network ပြင်ဆင်ခြင်း" value="${esc(t.title)}"></div><div class="field full"><label for="details">အလုပ်အသေးစိတ်</label><textarea id="details" name="details" rows="3" maxlength="10000" placeholder="လုပ်ဆောင်ရမည့်အချက်များနှင့် မျှော်မှန်းထားသော ရလဒ်…">${esc(t.details)}</textarea></div><div class="field full"><span class="field-label">တာဝန်ယူမည့် ဝန်ထမ်းများ <span class="required">*</span></span>${peopleInputs('assignees',t.assignees)}<small>တစ်ဦး သို့မဟုတ် အများအပြား ရွေးနိုင်သည်။</small></div><div class="field full"><span class="field-label">ပူးပေါင်းလုပ်မည့်သူများ — ဘယ်သူနဲ့ဘယ်သူ</span>${peopleInputs('collaborators',t.collaborators)}<small>ကူညီပူးပေါင်းလုပ်မည့်သူများကို ရွေးပါ။ တာဝန်ယူသူများကို ထပ်ရွေးစရာ မလိုပါ။</small></div><div class="field"><label for="start">စတင်မည့် နေ့ / အချိန် <span class="required">*</span></label><input id="start" name="start" type="datetime-local" required value="${wall(t.start)}"></div><div class="field"><label for="deadline">အပြီးလုပ်ရမည့် နေ့ / အချိန် <span class="required">*</span></label><input id="deadline" name="deadline" type="datetime-local" required value="${wall(t.deadline)}"></div><div class="field"><label for="priority">ဦးစားပေးအဆင့်</label><select id="priority" name="priority">${options(priorities,t.priority)}</select></div><div class="field"><label for="status">အလုပ်အခြေအနေ</label><select id="status" name="status">${options(statuses,t.status)}</select></div><div class="field"><label for="reminder">ပြီးစီးချိန်မတိုင်မီ သတိပေးရန်</label><select id="reminder" name="reminder">${[[0,'ပြီးစီးချိန်ရောက်လျှင်'],[15,'၁၅ မိနစ်အလို'],[30,'မိနစ် ၃၀ အလို'],[60,'၁ နာရီအလို'],[1440,'၁ ရက်အလို']].map(([v,l])=>`<option value="${v}" ${t.reminder===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="form-progress">တိုးတက်မှု (%)</label><input class="input" id="form-progress" type="number" name="progress" min="0" max="100" step="1" value="${t.progress}" required></div></div></form>`,`<span class="muted" style="font-size:10px">* မဖြစ်မနေ ဖြည့်ရန်</span><button class="btn primary" type="submit" form="task-form">${ic('check')} ${existing?'ပြောင်းလဲမှု သိမ်းရန်':'တာဝန်ပေးအပ်ရန်'}</button>`);}
function detail(id){const t=S.tasks.find(t=>t.id===id);if(!t)return;const comments=S.comments.filter(c=>c.task_id===id),files=S.attachments.filter(a=>a.task_id===id);showModal(esc(t.title),`တာဝန်ပေးသူ: ${esc(person(t.createdBy)?.name||'Admin')} · နောက်ဆုံးပြင်ဆင်ချိန် ${esc(dateTime(t.updatedAt))}`,`<div class="detail-overview">${badge(t.status)}${badge(t.priority,priorities)}${late(t)?'<span class="badge urgent">သတ်မှတ်ချိန်ကျော်</span>':''}</div><p class="description">${esc(t.details||'အသေးစိတ် မထည့်ရသေးပါ။')}</p><div class="detail-info"><div><small>တာဝန်ယူသူများ</small><div class="names">${esc(names(t.assignees))}</div></div><div><small>ပူးပေါင်းလုပ်သူများ</small><div class="names">${esc(names(t.collaborators)||'မရှိသေးပါ')}</div></div><div><small>စတင်ချိန်</small><strong>${esc(dateTime(t.start))}</strong></div><div><small>အပြီးလုပ်ရမည့်ချိန်</small><strong class="${late(t)?'deadline late':''}">${esc(dateTime(t.deadline))}</strong></div></div><form id="progress-form" data-version="${t.version}" data-id="${id}"><div class="field"><label for="detail-status">အလုပ်အခြေအနေ</label><select id="detail-status" name="status">${options(statuses,t.status)}</select></div><div class="progress-control"><label for="detail-progress" style="font-size:11px">တိုးတက်မှု</label><input id="detail-progress" name="progress" type="range" min="0" max="100" step="5" value="${t.progress}"><output id="progress-output">${t.progress}%</output><button class="btn soft small" type="submit">သိမ်းရန်</button></div></form><div class="section-row"><h3>တွဲဖိုင်များ <small class="muted">(${files.length})</small></h3><label class="btn small" for="attachment-input">${ic('plus')} ဖိုင်တွဲရန်</label><input id="attachment-input" type="file" data-id="${id}" hidden></div><small class="muted" style="font-size:10px">တစ်ဖိုင် 10 MB အထိ · ${S.filesReady||demo?'ဖိုင်တွဲနိုင်သည်':'ဖိုင်သိုလှောင်မှု ချိတ်ဆက်ရန်လိုသည်'}</small><div>${files.map(attachmentMarkup).join('')}</div><div class="section-row"><h3>မှတ်ချက်များ <small class="muted">(${comments.length})</small></h3>${ic('chat')}</div>${comments.length?comments.map(c=>`<div class="comment">${avatar(person(c.employee_id))}<div><strong>${esc(person(c.employee_id)?.name||'ဝန်ထမ်း')}</strong><time>${esc(dateTime(c.created_at))}</time><p>${esc(c.body)}</p></div></div>`).join(''):'<p class="muted" style="font-size:11px">ပထမဆုံး မှတ်ချက်ကို ရေးပါ။</p>'}<form id="comment-form" class="comment-box" data-id="${id}"><textarea name="body" aria-label="မှတ်ချက်" required maxlength="4000" placeholder="အခြေအနေ၊ မေးခွန်း သို့မဟုတ် အကြံပြုချက် ရေးရန်…"></textarea><button class="btn primary" type="submit">${ic('arrow')} ပို့ရန်</button></form>`,isAdmin()?`${btn('ဖယ်ရှားရန်','delete-task','close','danger small',`data-id="${id}"`)}${btn('အသေးစိတ် ပြင်ရန်','edit-task','edit','',`data-id="${id}"`)}`:`<small class="muted">မိမိတာဝန်နှင့် ပူးပေါင်းအလုပ်များကိုသာ ပြင်နိုင်သည်။</small>${btn('ပိတ်ရန်','close-modal','check','')}`);}
function profileForm(){showModal('အမည်နှင့် ဌာန ပြင်ရန်',esc(S.me.email),'<form id="profile-form"><div class="field"><label for="profile-name">အမည် *</label><input id="profile-name" name="name" required maxlength="100" value="'+esc(S.me.name)+'"></div><div class="field"><label for="profile-department">ဌာန / အဖွဲ့</label><input id="profile-department" name="department" maxlength="100" value="'+esc(S.me.department)+'"></div></form>',btn('မလုပ်တော့ပါ','close-modal','close','')+'<button form="profile-form" type="submit" class="btn primary">သိမ်းရန်</button>');}
function photoField(p){return `<div class="employee-photo-editor">${p?avatar(p,true):'<span class="avatar large">+</span>'}<div class="field"><label for="employee-photo">ဝန်ထမ်းပုံ</label><input id="employee-photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp" ${demo?'disabled':''}><small>JPG, PNG သို့မဟုတ် WebP · 3 MB အောက်${demo?' · စမ်းသပ်မုဒ်တွင် မတင်နိုင်ပါ':''}</small></div></div>`;}
function validateEmployeePhoto(file){if(!file?.size)return false;if(file.size>3*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('JPG, PNG သို့မဟုတ် WebP ပုံ 3 MB အောက် ရွေးပါ');return true;}
async function uploadEmployeePhoto(id,file){if(!validateEmployeePhoto(file)||demo)return;const data=new FormData();data.set('photo',file);await request('/api/employees/'+id+'/photo','POST',data);}
function personForm(id){
 const p=person(id);if(!isAdmin()||(p&&!canManagePerson(p)))return;
 if(p){const roleFields=S.me.role==='ceo'&&p.role!=='ceo'?`<div class="field"><label for="role">အသုံးပြုခွင့်</label><select id="role" name="role">${options({employee:'ဝန်ထမ်း',admin:'Admin'},p.role)}</select></div><div class="field"><label><input type="checkbox" name="active" ${p.active?'checked':''}> အကောင့်အသုံးပြုခွင့် ဖွင့်ထားရန်</label></div>`:p.role==='ceo'?'<div class="note">CEO ခွင့်ကို ဆက်ထိန်းထားပြီး အမည်၊ email၊ ဌာနနှင့် ပုံကို ပြင်နိုင်သည်။</div>':'';showModal('ဝန်ထမ်းအချက်အလက် ပြင်ရန်',esc(p.name),`<form id="person-role-form" data-id="${id}">${photoField(p)}<div class="form-grid"><div class="field full"><label for="edit-name">အမည် *</label><input id="edit-name" name="name" required maxlength="100" value="${esc(p.name)}"></div><div class="field full"><label for="edit-email">အကောင့်အီးမေးလ် *</label><input id="edit-email" name="email" type="email" required maxlength="254" value="${esc(p.email)}"><small>နောက်တစ်ကြိမ်မှစ၍ email အသစ်ဖြင့် ဝင်ရောက်ရမည်။</small></div><div class="field full"><label for="edit-department">ဌာန / အဖွဲ့</label><input id="edit-department" name="department" maxlength="100" value="${esc(p.department)}"></div></div>${roleFields}</form>`,btn('မလုပ်တော့ပါ','close-modal','close','')+'<button form="person-role-form" type="submit" class="btn primary">သိမ်းရန်</button>');return;}
 showModal('ဝန်ထမ်းအသစ် ထည့်ရန်','အကောင့်အီးမေးလ်၊ ပုံနှင့် အသုံးပြုခွင့်ကို သတ်မှတ်ပါ။',`<form id="person-form">${photoField()}<div class="form-grid"><div class="field full"><label for="person-name">ဝန်ထမ်းအမည် *</label><input type="text" id="person-name" name="name" required maxlength="100" placeholder="အမည်အပြည့်အစုံ"></div><div class="field full"><label for="person-email">အကောင့်အီးမေးလ် *</label><input id="person-email" name="email" type="email" required maxlength="254" placeholder="employee@company.com"><small>ဤအီးမေးလ်နှင့် ကိုယ်တိုင်သတ်မှတ်ထားသော password ဖြင့် ဝင်နိုင်မည်။</small></div><div class="field"><label for="department">ဌာန / အဖွဲ့</label><input id="department" name="department" type="text" maxlength="100" placeholder="ဥပမာ — IT Support"></div><div class="field"><label for="role">အသုံးပြုခွင့်</label><select id="role" name="role">${options(S.me.role==='ceo'?{employee:'ဝန်ထမ်း',admin:'Admin'}:{employee:'ဝန်ထမ်း'},'employee')}</select></div></div><div class="note warning">ထည့်ပြီးနောက် ယာယီ password ပြပေးမည်။ ပထမဆုံးဝင်ချိန်တွင် အနည်းဆုံး ၈ လုံးရှိသော password အသစ် ပြောင်းရမည်။</div></form>`,btn('မလုပ်တော့ပါ','close-modal','close','')+'<button form="person-form" type="submit" class="btn primary">ဝန်ထမ်းထည့်ရန်</button>');
}
let activationToken='',activationAccount=null;
function passwordFields(current=false){return `${current?'<div class="field"><label for="current-password">လက်ရှိ password</label><input id="current-password" name="currentPassword" type="password" autocomplete="current-password" required maxlength="256"></div>':''}<div class="field"><label for="new-password">Password အသစ်</label><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="8" maxlength="72" required><small>အနည်းဆုံး စာလုံး ၈ လုံး။ မြန်မာစာပါလျှင် UTF-8 ၇၂ bytes အတွင်း ဖြစ်ရမည်။</small></div><div class="field"><label for="confirm-password">Password အသစ် ထပ်ဖြည့်ပါ</label><input id="confirm-password" name="confirmPassword" type="password" autocomplete="new-password" required maxlength="72"></div>`;}
function lockSession(){S={me:null,people:[],tasks:[],comments:[],attachments:[],activity:[],filesReady:false};page='dashboard';filter='all';query='';modal.close();loginScreen();}
function loginScreen(mode='signin',error=''){const activate=mode==='activate';app.innerHTML=`<div class="login-screen"><section class="login-story">${brand()}<h1>အလုပ်တိုင်း ရှင်းလင်းဖို့။<br>အဖွဲ့တိုင်း တိုးတက်ဖို့။</h1><p>တာဝန်ပေးအပ်ခြင်း၊ ပူးပေါင်းဆောင်ရွက်ခြင်းနဲ့ တိုးတက်မှုကို Linn IT Solutions အတွက် တစ်နေရာတည်းမှာ စီမံပါ။</p><div class="uppercase">Clarity. Collaboration. Progress.</div></section><section class="login-form"><div class="login-box">${brand()}<h2>${activate?'Password သတ်မှတ်ပါ':'အဖွဲ့သို့ ဝင်ရောက်ပါ'}</h2><p>${activate?esc(activationAccount?.name)+' · '+esc(activationAccount?.email):'သင့် email နှင့် password ဖြင့် ဝင်ရောက်ပါ။'}</p>${error?`<div class="form-error visible" role="alert">${esc(error)}</div>`:''}${!error||!activate?`<form id="${activate?'activate-form':'login-form'}"><div id="form-error" class="form-error" role="alert"></div>${activate?passwordFields():`<div class="field"><label for="login-email">Email</label><input id="login-email" name="email" type="email" autocomplete="username" autocapitalize="none" required maxlength="254" placeholder="employee@linn.com.mm"></div><div class="field"><label for="login-password">Password</label><input id="login-password" name="password" type="password" autocomplete="current-password" required maxlength="256"></div>`}<button type="submit" class="btn primary">${activate?'Password သိမ်းပြီး ဝင်ရောက်ရန်':'ဝင်ရောက်ရန်'}</button></form>`:''}${activate?btn('Login သို့ ပြန်သွားရန်','back-login','arrow',''):btn('Password မေ့နေပါသလား','forgot-password','shield','')}<button class="btn" data-action="start-demo">${ic('grid')} နမူနာဖြင့် စမ်းကြည့်ရန်</button><p class="fine">မြန်မာဘာသာ · မြန်မာစံတော်ချိန်<br>Admin ခွင့်ပြုထားသော ဝန်ထမ်းများသာ ဝင်နိုင်သည်။<br>အသုံးပြုပြီးပါက မျှဝေသုံးသောဖုန်းမှ ထွက်ပါ။</p></div></section></div>`;}
function changePasswordForm(){showModal('Password ပြောင်းရန်','တခြားဖုန်းများမှ session များကို ပိတ်ပေးမည်။',`<form id="password-form"><div id="form-error" class="form-error" role="alert"></div>${passwordFields(true)}</form>`,btn('မလုပ်တော့ပါ','close-modal','close','')+'<button form="password-form" type="submit" class="btn primary">သိမ်းရန်</button>');}
function requiredPasswordScreen(me){S={me:null,people:[],tasks:[],comments:[],attachments:[],activity:[],filesReady:false};modal.close();app.innerHTML=`<div class="login-screen"><section class="login-story">${brand()}<h1>သင့်အကောင့်အတွက်<br>Password အသစ် သတ်မှတ်ပါ။</h1><p>ယာယီ password ကို ပြောင်းပြီးမှ အလုပ်တာဝန်များကို ကြည့်နိုင်ပါမည်။</p></section><section class="login-form"><div class="login-box">${brand()}<h2>Password ပြောင်းရန် လိုအပ်သည်</h2><p>${esc(me?.name)} · ${esc(me?.email)}</p><form id="required-password-form"><div id="form-error" class="form-error" role="alert"></div>${passwordFields()}<button type="submit" class="btn primary">Password ပြောင်းပြီး ဝင်ရောက်ရန်</button></form>${btn('အကောင့်မှ ထွက်ရန်','logout','logout','')}</div></section></div>`;}
function showTemporaryPassword(r){showModal('ဝန်ထမ်းအတွက် ယာယီ password',esc(r.email),`<div class="field"><label for="temporary-password">ယာယီ password</label><input id="temporary-password" type="text" readonly value="${esc(r.temporaryPassword)}"></div><p class="description">ဤ email နှင့် ယာယီ password ကို ဝန်ထမ်းထံ ပေးပါ။ ပထမဆုံးဝင်ချိန်တွင် password အသစ် ပြောင်းရမည်။ အနည်းဆုံး ၈ လုံး သတ်မှတ်နိုင်သည်။</p>`,btn('ပိတ်ရန်','close-modal','close'));}
async function setTemporaryPassword(id){const p=person(id);if(p?.linked&&!confirm(p.name+' ကို ယာယီ password ပြန်ပေးမည်လား။ လက်ရှိ password နှင့် session များ ပိတ်သွားမည်။'))return;const r=await request('/api/auth/temporary-password','POST',{employeeId:id});await load();showTemporaryPassword(r);}
async function invitePerson(id){const p=person(id);if(p?.linked&&!confirm(p.name+' အတွက် password ပြန်သတ်မှတ်ရန် link အသစ် ထုတ်မည်လား။ Link အဟောင်း ပျက်သွားမည်။'))return;const r=await request('/api/auth/invite','POST',{employeeId:id});showModal('Password သတ်မှတ်ရန် link',esc(r.email),`<p class="description">ဤ link ကို သက်ဆိုင်ရာဝန်ထမ်းထံသာ ပေးပါ။ ၂၄ နာရီအတွင်း တစ်ကြိမ်သာ အသုံးပြုနိုင်သည်။ Password သတ်မှတ်ပြီးနောက် email/password ဖြင့် ဝင်နိုင်သည်။</p><div class="field"><label for="activation-link">ဝန်ထမ်းအတွက် link</label><input id="activation-link" type="text" readonly value="${esc(r.url)}"></div><p class="fine">သက်တမ်းကုန်ချိန် — ${esc(dateTime(r.expiresAt))}<br>အီးမေးလ် အလိုအလျောက် မပို့ပါ။</p>`,btn('Link ကူးယူရန်','copy-invite','link','primary')+btn('ပိတ်ရန်','close-modal','close',''));}
async function load(renderPage=true,knownSession=null){const session=knownSession||await request('/api/session');if(session.me?.mustChangePassword){requiredPasswordScreen(session.me);return;}const [state,noticeResult]=await Promise.all([request('/api/state'),request('/api/notifications').catch(()=>null)]);S=state;if(noticeResult){S.notices=noticeResult.items;S.pushConfigured=noticeResult.pushConfigured;S.pushPublicKey=noticeResult.publicKey;noticesLoaded=true;}else noticesLoaded=false;stale=false;if(renderPage)render();await restorePush();await checkReminders();openHashTask();}
async function init(){try{const token=new URLSearchParams(location.hash.slice(1)).get('activate');if(token){activationToken=token;activationAccount=await request('/api/auth/activation','POST',{token});loginScreen('activate');return;}const session=await request('/api/session');if(!session.signedIn){loginScreen();return;}if(session.me?.mustChangePassword){requiredPasswordScreen(session.me);return;}await load(true,session);}catch(e){loginScreen(activationToken?'activate':'signin',e.message);}}
async function withForm(form,fn){const buttons=[...document.querySelectorAll(`button[form="${form.id}"],#${form.id} button`)];buttons.forEach(b=>b.disabled=true);const e=$('#form-error');if(e)e.classList.remove('visible');try{await fn();}catch(err){if(e){e.textContent=err.message;e.classList.add('visible');e.scrollIntoView({block:'nearest'});}else toast(err.message);}finally{buttons.forEach(b=>b.disabled=false);}}
document.addEventListener('submit',async e=>{const form=e.target;if(!['task-form','person-form','person-role-form','profile-form','progress-form','comment-form','login-form','activate-form','password-form','required-password-form'].includes(form.id))return;e.preventDefault();await withForm(form,async()=>{const fd=new FormData(form),id=form.dataset.id;if(form.id==='login-form'){await request('/api/auth/login','POST',{email:fd.get('email'),password:fd.get('password')});form.reset();await load();toast('အကောင့်ဝင်ပြီးပါပြီ');return;}
 if(form.id==='activate-form'||form.id==='password-form'||form.id==='required-password-form'){const password=fd.get('password');if(password!==fd.get('confirmPassword'))throw Error('Password နှစ်ခု မတူပါ');await request(form.id==='activate-form'?'/api/auth/activate':'/api/auth/change-password','POST',{password,currentPassword:fd.get('currentPassword'),token:activationToken});form.reset();activationToken='';activationAccount=null;history.replaceState(null,'','/');modal.close();await load();toast('Password သိမ်းပြီးပါပြီ');return;}
 if(form.id==='task-form'){const assignees=fd.getAll('assignees');if(!assignees.length)throw Error('တာဝန်ယူသူ အနည်းဆုံး တစ်ဦးရွေးပါ');if(new Date(fd.get('deadline')+'+06:30')<=new Date(fd.get('start')+'+06:30'))throw Error('ပြီးစီးချိန်သည် စတင်ချိန်ထက် နောက်ကျရပါမည်');const data={title:fd.get('title'),details:fd.get('details'),assignees,collaborators:fd.getAll('collaborators').filter(x=>!assignees.includes(x)),start:toUTC(fd.get('start')),deadline:toUTC(fd.get('deadline')),priority:fd.get('priority'),status:fd.get('status'),progress:Number(fd.get('progress')),reminder:Number(fd.get('reminder'))};if(id)data.version=Number(form.dataset.version);const r=await request(id?'/api/tasks/'+id:'/api/tasks',id?'PATCH':'POST',data);await load();detail(id||r.id);toast(id?'အလုပ်ကို ပြင်ဆင်ပြီးပါပြီ':'အလုပ်တာဝန် ပေးအပ်ပြီးပါပြီ');}
 else if(form.id==='person-form'){const photo=fd.get('photo');validateEmployeePhoto(photo);const created=await request('/api/employees','POST',{name:fd.get('name'),email:fd.get('email'),department:fd.get('department'),role:fd.get('role')});let photoError='';try{await uploadEmployeePhoto(created.id,photo);}catch(error){photoError=error.message;}modal.close();await load();toast(photoError?'ဝန်ထမ်းထည့်ပြီးသော်လည်း ပုံတင်မရပါ — '+photoError:'ဝန်ထမ်းနှင့် ပုံ သိမ်းပြီးပါပြီ');const p=S.people.find(p=>p.email.toLowerCase()===String(fd.get('email')).trim().toLowerCase());if(!demo&&created.temporaryPassword)showTemporaryPassword(created);else if(p&&!demo)await invitePerson(p.id);}
 else if(form.id==='profile-form'){await request('/api/profile','PATCH',{name:fd.get('name'),department:fd.get('department')});modal.close();await load();toast('အမည်နှင့် ဌာန သိမ်းပြီးပါပြီ');}
 else if(form.id==='person-role-form'){const photo=fd.get('photo');validateEmployeePhoto(photo);await request('/api/employees/'+id,'PATCH',{name:fd.get('name'),email:fd.get('email'),department:fd.get('department'),...(fd.has('role')?{role:fd.get('role'),active:fd.has('active')}:{})});let photoError='';try{await uploadEmployeePhoto(id,photo);}catch(error){photoError=error.message;}modal.close();await load();toast(photoError?'အချက်အလက်သိမ်းပြီးသော်လည်း ပုံတင်မရပါ — '+photoError:'ဝန်ထမ်းအချက်အလက် သိမ်းပြီးပါပြီ');}
 else if(form.id==='progress-form'){await request('/api/tasks/'+id,'PATCH',{status:fd.get('status'),progress:Number(fd.get('progress')),version:Number(form.dataset.version)});await load();detail(id);toast('တိုးတက်မှု သိမ်းပြီးပါပြီ');}
 else if(form.id==='comment-form'){await request('/api/tasks/'+id+'/comments','POST',{body:fd.get('body')});await load();detail(id);toast('မှတ်ချက် ပို့ပြီးပါပြီ');}
 });});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-page],[data-action],[data-task],[data-filter]');if(!el)return;if(el.dataset.page){goPage(el.dataset.page);return;}if(el.dataset.task){detail(el.dataset.task);return;}if(el.dataset.filter){filter=el.dataset.filter;render();return;}const action=el.dataset.action,id=el.dataset.id;
 try{if(action==='preview-photo')previewPhoto(id,el.dataset.name);else if(action==='close-photo')closePhoto();else if(action==='people-view'){peopleView=el.dataset.view==='table'?'table':'cards';try{localStorage.setItem('linn-people-view',peopleView);}catch{}render();}else if(action==='logout'){await disconnectPush();await request('/api/auth/logout','POST',{});lockSession();toast('အကောင့်မှ ထွက်ပြီးပါပြီ');}else if(action==='edit-profile')profileForm();else if(action==='test-notifications')await testNotifications();else if(action==='read-notifications'){await request('/api/notifications/read','POST',{all:true});await load();}else if(action==='read-notification'){await request('/api/notifications/read','POST',{id});await load();}else if(action==='open-notification'){await request('/api/notifications/read','POST',{id});await load();detail(el.dataset.taskId);}else if(action==='change-password')changePasswordForm();else if(action==='temporary-person')await setTemporaryPassword(id);else if(action==='invite-person')await invitePerson(id);else if(action==='copy-invite'){const field=$('#activation-link');try{await navigator.clipboard.writeText(field.value);toast('Link ကူးယူပြီးပါပြီ');}catch{field.select();toast('Link ကို ရွေးထားပါပြီ။ Copy ကို နှိပ်ပါ');}}else if(action==='back-login'){activationToken='';activationAccount=null;history.replaceState(null,'','/');loginScreen();}else if(action==='forgot-password'){showModal('Password ပြန်သတ်မှတ်ရန်','Admin / CEO ထံ ဆက်သွယ်ပါ။','<p class="description">Admin က ဝန်ထမ်းများစာရင်းမှ ယာယီ password ပြန်ပေးနိုင်သည်။ ယာယီ password နှင့် ဝင်ပြီး မိမိ password အသစ်ကို ပြောင်းပါ။</p>',btn('ပိတ်ရန်','close-modal','close'));}else if(action==='new-task')taskForm();else if(action==='edit-task')taskForm(id);else if(action==='close-modal')modal.close();else if(action==='new-person')personForm();else if(action==='edit-person')personForm(id);else if(action==='refresh'){await load();toast('ဒေတာ ပြန်တင်ပြီးပါပြီ');}else if(action==='delete-task'){if(confirm('ဤအလုပ်ကို ဖယ်ရှားမည်လား။ အလုပ်စာရင်းတွင် မပြတော့ပါ။')){await request('/api/tasks/'+id,'DELETE');modal.close();await load();toast('ဖယ်ရှားပြီးပါပြီ');}}else if(action==='install')await install();else if(action==='enable-notifications')await enableNotifications();else if(action==='export-tasks')exportCSV();else if(action==='backup')download('linn-tasks-backup-'+wall(new Date()).slice(0,10)+'.json',JSON.stringify({exportedAt:new Date().toISOString(),...S},null,2),'application/json');else if(action==='start-demo')startDemo();else if(action==='exit-demo'){demo=false;S.me=null;modal.close();page='dashboard';filter='all';await init();}else if(action==='reset-demo'){if(confirm('စမ်းသပ်ဒေတာကို အစကနေ ပြန်စမည်လား။')){localStorage.removeItem('linn-demo-v1');startDemo();}}}catch(err){toast(err.message);}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#photo-viewer')?.classList.contains('open')){e.preventDefault();closePhoto();return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-task]')){e.preventDefault();detail(e.target.dataset.task);}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='status-filter'){filter=el.value;render();}else if(el.id==='priority-filter'){priorityFilter=el.value;render();}else if(el.id==='person-filter'){personFilter=el.value;render();}else if(el.id==='demo-role'){S.me=person(el.value);page='dashboard';filter='all';await load();}else if(el.id==='employee-photo'){const file=el.files[0];if(!file)return;try{validateEmployeePhoto(file);const holder=el.closest('.employee-photo-editor')?.querySelector('.avatar'),image=new Image(),url=URL.createObjectURL(file);image.alt='ရွေးထားသော ဝန်ထမ်းပုံ';image.onload=()=>URL.revokeObjectURL(url);image.src=url;holder?.classList.add('has-photo');holder?.replaceChildren(image);}catch(err){el.value='';toast(err.message);}}else if(el.id==='attachment-input'){const file=el.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('ဖိုင်တစ်ဖိုင် 10 MB အများဆုံးသာ တင်နိုင်သည်');const fd=new FormData();fd.set('file',file);el.disabled=true;await request('/api/tasks/'+el.dataset.id+'/attachments','POST',fd);await load();detail(el.dataset.id);toast('ဖိုင်တင်ပြီးပါပြီ');}catch(err){toast(err.message);}finally{el.disabled=false;}}});
document.addEventListener('input',e=>{if(e.target.id==='detail-progress')$('#progress-output').textContent=e.target.value+'%';else if(e.target.id==='task-search'){query=e.target.value;const pos=e.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const field=$('#task-search');field?.focus();try{field?.setSelectionRange(pos,pos);}catch{}},120);}});
const isStandalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const isIOS=()=>/iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
